public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    double x = box.getX();
    double width = box.getWidth();
    double halfWidth = width / 2.0;
    double x1 = x;
    double x2 = x + halfWidth;
    return new Pair<>(new Box2D(x1, box.getY(), halfWidth, box.getHeight()), new Box2D(x2, box.getY(), halfWidth, box.getHeight()));
}

